// Single source of truth for what gets published (and precached by the service worker).
// Paths are relative to the repo root and keep the same path inside _site/.
// To publish a new file: add it here (the build fails if it is missing or if index.html/manifest references
// a local file that is not listed). sw.js and .nojekyll are generated by scripts/build.ts and not listed.
export const SITE_FILES: string[] = [
  'index.html',
  'manifest.webmanifest',
  'dist/main.js',
  'src/style.css',
  'icons/apple-touch-icon.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-512.png',
];
